### C++

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <queue>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> cores(n);
        for (int i = 0; i < n; ++i) {
            cin >> cores[i];
        }

        unordered_map<int, int> expire;   // 截止时间
        unordered_map<int, int> cnt;      // 出现次数
        // 小根堆
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

        int active = 0, max_active = 0, time = 0;

        for (int c : cores) {
            ++time;

            // 衰减清理
            while (!pq.empty() && pq.top().first == time) {
                auto [et, typ] = pq.top();
                pq.pop();
                auto it = expire.find(typ);
                if (it != expire.end() && it->second == et) {
                    expire.erase(it);
                    --active;
                }
            }

            // 更新出现次数
            int k = cnt[c] + 1;
            cnt[c] = k;
            int delta = k * k;

            auto it = expire.find(c);
            if (it != expire.end()) {
                // 处于激活状态，延长截止时间
                it->second += delta;
            } else {
                // 重新激活
                expire[c] = time + delta;
                ++active;
            }

            pq.emplace(expire[c], c);
            if (active > max_active) max_active = active;
        }

        cout << max_active << "\n";
    }
    return 0;
}
